# %% [markdown]
# # specs_novel — G0.1-R2, Kaggle leg: fixed peaks + DreaMS on T4, internet off
#
# **Generated by `build/mk_novel_p0.py` — do not hand-edit.** Pre-registered in
# `specs_novel/gate_report.md` → *G0.1-R2*.
#
# Settings: **GPU T4 ×2**, **Internet OFF**. Inputs: the competition data (for `train.parquet`) and
# the dataset **casmi26-novel-lx**, uploaded from `_novel/lx/kaggle_upload/` by
# `casmi_novel_lx_reembed_colab.ipynb`.
#
# Unlike the G0.1 Kaggle leg, the peaks are **rebuilt from `train.parquet` here**, not read from the
# stored ones. The leg passes when they are byte-identical with the GPU host's **and** the vectors
# embedded from them on `cuda:1` reach cosine ≥ 0.999 with the new cache on every row. ~5 min.

# %%
import glob, hashlib, json, subprocess, sys, time
from pathlib import Path
import numpy as np
import pyarrow.parquet as pq
import torch

def find_file(name):
    hits = sorted(glob.glob(f"/kaggle/input/**/{name}", recursive=True), key=len)
    assert hits, f"{name} not found under /kaggle/input -- are the competition data and casmi26-novel-lx attached?"
    return hits[0]

UP = Path(find_file("manifest_lx.json")).parent
TRAIN = Path(find_file("test.parquet")).parent / "train.parquet"
MAN = json.loads((UP / "manifest_lx.json").read_text())
print(f"dataset {UP}\ntrain {TRAIN}\nmanifest {json.dumps(MAN, indent=1)}")
print(subprocess.run("nvidia-smi --query-gpu=index,name,driver_version --format=csv,noheader",
                     shell=True, capture_output=True, text=True).stdout)
RESULT = {"python": sys.version.split()[0], "torch": torch.__version__, "started": time.strftime("%Y-%m-%d %H:%M")}

# %% [markdown]
# ## Sources (embedded verbatim, checked against the GPU run's manifest)

# %%
DREAMS_INFER_SRC = None  # @@DREAMS_INFER@@
NOVEL_LX_SRC = None  # @@NOVEL_LX@@

SRC = Path("/kaggle/working/novel_src")
SRC.mkdir(parents=True, exist_ok=True)
for fname, text, key in [("dreams_infer.py", DREAMS_INFER_SRC, "dreams_infer_sha1"),
                         ("novel_lx.py", NOVEL_LX_SRC, "novel_lx_sha1")]:
    got = hashlib.sha1(text.encode("utf-8")).hexdigest()
    assert got == MAN[key], f"{fname}: notebook source {got} != the GPU run's {MAN[key]}"
    (SRC / fname).write_text(text, encoding="utf-8")
sys.path.insert(0, str(SRC))
import dreams_infer as di
import novel_lx as lx
RESULT["host"] = lx.host_info()
print(RESULT)

# %% [markdown]
# ## Rebuild the `parity_lx` peaks from `train.parquet`

# %%
Z = dict(np.load(UP / "parity_lx.npz"))
assert "emb" in Z, "parity_lx.npz has no cache vectors -- upload the one written after the GPU run finished"
REF = lx.unpack_peaks(Z["mz"], Z["it"], Z["off"])
TR, PREC = Z["train_row"], Z["prec"]
ids = pq.read_table(TRAIN, columns=["inchikey14", "adduct", "precursor_mz"]).to_pandas().iloc[TR]
ids_ok = bool((ids.inchikey14.astype(str).to_numpy() == Z["inchikey14"]).all()
              and (ids.adduct.astype(str).to_numpy() == Z["adduct"]).all()
              and (ids.precursor_mz.to_numpy(np.float64) == PREC).all())
assert ids_ok, "Kaggle train.parquet rows do not match parity_lx identities"

t0 = time.time()
PL = [None] * len(TR)
lx.stream_rows(TRAIN, TR, lambda k, mz, it: PL.__setitem__(k, di.dreams_peaks(mz, it, PREC[k])))
diffs = lx.peak_diffs(PL, REF)
digest = lx.peaks_digest(PL, PREC)
same = not diffs and digest == MAN["parity_peaks_digest"]
print(f"peaks byte-identical with the GPU host: {same} ({len(diffs)} rows differ); {time.time() - t0:.0f}s")

# %% [markdown]
# ## Embed the Kaggle-rebuilt peaks on `cuda:1` and compare with the new cache

# %%
n_gpu = torch.cuda.device_count()
DEV = "cuda:1" if n_gpu >= 2 else ("cuda:0" if n_gpu == 1 else "cpu")
torch.backends.cuda.matmul.allow_tf32 = False
torch.backends.cudnn.allow_tf32 = False
model, _ = di.load_dreams(UP / "dreams_embed.pt", device=DEV, expect_sha1=MAN["dreams_embed_sha1"])
di.dreams_embed(model, PL[:8], PREC[:8])                  # warm-up
E = di.dreams_embed(model, PL, PREC, batch_size=64)
cos = lx.rowcos(E, Z["emb"])
tie = Z["tie"].astype(bool)
worst = np.argsort(cos)[:5]
print(f"Kaggle vs new cache: min {cos.min():.9f}  median {np.median(cos):.9f}  (tie rows min {cos[tie].min():.9f})")
print(f"worst: {[(int(Z['row'][i]), str(Z['lib'][i]), bool(tie[i]), float(cos[i])) for i in worst]}")

# %%
passed = bool(same and DEV.startswith("cuda") and cos.min() >= MAN["cos_min"])
RESULT["kaggle_leg"] = dict(device=DEV, n_gpu=n_gpu, n=len(TR), n_tie=int(tie.sum()), ids_ok=ids_ok,
                            peaks_identical=same, n_diff=len(diffs), diff_rows=[int(Z["row"][i]) for i in diffs[:20]],
                            peaks_digest=digest, cos_min=float(cos.min()), cos_median=float(np.median(cos)),
                            cos_tie_min=float(cos[tie].min()), threshold=MAN["cos_min"], passed=passed)
RESULT["finished"] = time.strftime("%Y-%m-%d %H:%M")
Path("/kaggle/working/lx_kaggle.json").write_text(json.dumps(RESULT, indent=1))
print("=" * 70)
print(json.dumps(RESULT, indent=1))
print("=" * 70)
print(f"G0.1-R2 Kaggle leg: {'PASS' if passed else 'FAIL'}")
